const en=document.documentElement.lang==='en';
const catalog=document.querySelector('#catalog'),search=document.querySelector('#search'),category=document.querySelector('#category');let components=[];const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const slug=s=>s.replace(/[^a-zA-Z0-9]+/g,'-');
const descriptions=en?{Offset:'Creates offsets of a planar polyline and returns its straight skeleton.',Skeleton2d:'Computes the straight skeleton of a planar polyline with per-edge weights.',Roofer:'Generates roof meshes from a polyline and slope values.'}:{Offset:'Cria offsets de uma polilinha planar e devolve o seu esqueleto.',Skeleton2d:'Calcula o esqueleto reto de uma polilinha planar, com pesos por aresta.',Roofer:'Gera malhas de cobertura a partir de uma polilinha e valores de inclinação.'};
function params(list){return list.map(p=>`<div class="param"><strong>${escape(p.nick)} · ${escape(p.name)}</strong><p>${escape(p.desc)}</p><small>${escape(p.type)} · ${escape(p.access)}${p.default?(en?' · Default: ':' · Predefinição: ')+escape(p.default):''}${p.optional?(en?' · Optional':' · Opcional'):''}</small></div>`).join('')}
function render(){let q=search.value.toLowerCase();let filtered=components.filter(c=>(!category.value||c.group===category.value)&&[c.name,c.nick,c.desc,c.group,descriptions[c.name]||''].join(' ').toLowerCase().includes(q));catalog.innerHTML=[...new Set(filtered.map(c=>c.group))].sort().map(group=>`<section class="category-group"><h3>${escape(group)}</h3><div class="category-components">${filtered.filter(c=>c.group===group).sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<details id="component-${slug(c.name)}"><summary><span class="badge"><img src="${escape(c.icon)}" alt="" width="32" height="32" loading="lazy"></span><span><b>${escape(c.name)}</b><small>${escape(c.group)} · ${c.inputs.length} ${en?"inputs":"entradas"} / ${c.outputs.length} ${en?"outputs":"saídas"}</small></span><span class="plus" aria-hidden="true">+</span></summary><div class="detail"><p>${escape(descriptions[c.name]||c.desc)}</p><h4>${en?"Inputs":"Entradas"}</h4>${params(c.inputs)}<h4>${en?"Outputs":"Saídas"}</h4>${params(c.outputs)}<p class="source">${en?"Source":"Referência"}: ${escape(c.file)}</p></div></details>`).join('')}</div></section>`).join('');document.querySelector('#count').textContent=`${filtered.length} ${en?"of":"de"} ${components.length} ${en?"components":"componentes"}`;document.querySelector('#empty').hidden=filtered.length!==0}
function reveal(){if(!location.hash.startsWith('#component-'))return;search.value='';category.value='';render();let el=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(el){el.open=true;el.scrollIntoView({block:'start'})}}
fetch('components.json').then(r=>{if(!r.ok)throw Error('load');return r.json()}).then(data=>{components=data;[...new Set(data.map(c=>c.group))].sort().forEach(g=>{let o=document.createElement('option');o.value=g;o.textContent=g;category.append(o)});render();reveal()}).catch(()=>{catalog.textContent=en?'Could not load the reference. Refresh the page to try again.':'Não foi possível carregar a referência. Atualize a página para tentar novamente.'});search.addEventListener('input',render);category.addEventListener('change',render);window.addEventListener('hashchange',reveal);document.querySelectorAll('a[href^="#component-"]').forEach(a=>a.addEventListener('click',()=>setTimeout(reveal,0)));
